def comps(color_cells):
    seen=set(); out=[]
    for p in color_cells:
        if p in seen: continue
        st=[p]; comp=[]
        while st:
            q=st.pop()
            if q in seen: continue
            seen.add(q); comp.append(q)
            for dr,dc in((1,0),(-1,0),(0,1),(0,-1)): st.append((q[0]+dr,q[1]+dc))
        out.append(comp)
    return out
def analyze(n):
    gi=G[f'Demo pair {n} input']; go=G[f'Demo pair {n} output']
    fr=find_frame(gi)[0][1]
    r0,r1,c0,c1=fr
    cnt=Counter(x for row in gi for x in row); bg=cnt.most_common(1)[0][0]
    # interior comps (strict interior)
    inner=[(r,c) for r in range(r0+1,r1) for c in range(c0+1,c1)]
    ic=comps([(r,c) for r,c in inner if gi[r][c]!=bg])
    ibl={col:comp for col,comp in [(gi[r][c],[(r,c)]) for r,c in inner]}
    ib={}
    for col,cs in ic:
        ib[col]=[sorted(cc) for cc in comps(cs)][0] if len(cs)==1 else sorted(cs)
    # proper labeling
    iblabeled={(gi[p[0]][p[1]],sorted(p)) for p in []}
    labeled={}
    for col,comp in ic:
        colored=[(col,p) for p in comp]
        labeled[col]=sorted(p for _,p in colored)
    print(f'--- demo{n} bg={bg} frame={fr}')
    for col,cells in labeled.items():
        rs=[r for r,c in cells]; cs_=[c for r,c in cells]
        print(f'  block color {col}: rows{min(rs)}-{max(rs)} cols{min(cs_)}-{max(cs_)}, size={len(cells)}')
