# Find connected frame components of color 3 in output:
def comps(g,v):
    R,C=len(g),len(g[0]); seen=[[False]*C for _ in range(R)]; out=[]
    for r in range(R):
        for c in range(C):
            if g[r][c]==v and not seen[r][c]:
                st=[(r,c)];seen[r][c]=True;comp=[]
                while st:
                    a,b=st.pop();comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<R and 0<=y<C and g[x][y]==v and not seen[x][y]:
                            seen[x][y]=True;st.append((x,y))
                out.append(comp)
    return out
